WITH wanted AS (SELECT oid FROM pg_roles WHERE rolname = $1), acl AS ( SELECT 'database'::text AS object_kind, d.datname::text AS schema_name, d.datname::text AS object_name, x.privilege_type::text, x.is_grantable FROM pg_database d CROSS JOIN LATERAL aclexplode(COALESCE(d.datacl, acldefault('d', d.datdba))) x WHERE d.datname = current_database() AND x.grantee = (SELECT oid FROM wanted) UNION ALL SELECT 'schema', n.nspname::text, n.nspname::text, x.privilege_type::text, x.is_grantable FROM pg_namespace n CROSS JOIN LATERAL aclexplode(COALESCE(n.nspacl, acldefault('n', n.nspowner))) x WHERE x.grantee = (SELECT oid FROM wanted) UNION ALL SELECT 'relation', n.nspname::text, c.relname::text, x.privilege_type::text, x.is_grantable FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace CROSS JOIN LATERAL aclexplode(COALESCE(c.relacl, acldefault('r', c.relowner))) x WHERE x.grantee = (SELECT oid FROM wanted) UNION ALL SELECT 'routine', n.nspname::text, p.proname::text, x.privilege_type::text, x.is_grantable FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace CROSS JOIN LATERAL aclexplode(COALESCE(p.proacl, acldefault('f', p.proowner))) x WHERE x.grantee = (SELECT oid FROM wanted) UNION ALL SELECT 'column', n.nspname::text, c.relname::text || '.' || a.attname::text, x.privilege_type::text, x.is_grantable FROM pg_attribute a JOIN pg_class c ON c.oid = a.attrelid JOIN pg_namespace n ON n.oid = c.relnamespace CROSS JOIN LATERAL aclexplode(a.attacl) x WHERE x.grantee = (SELECT oid FROM wanted) UNION ALL SELECT 'type', n.nspname::text, t.typname::text, x.privilege_type::text, x.is_grantable FROM pg_type t JOIN pg_namespace n ON n.oid = t.typnamespace CROSS JOIN LATERAL aclexplode(COALESCE(t.typacl, acldefault('T', t.typowner))) x WHERE x.grantee = (SELECT oid FROM wanted) UNION ALL SELECT 'language', ''::text, l.lanname::text, x.privilege_type::text, x.is_grantable FROM pg_language l CROSS JOIN LATERAL aclexplode(COALESCE(l.lanacl, acldefault('l', l.lanowner))) x WHERE x.grantee = (SELECT oid FROM wanted) UNION ALL SELECT 'large-object', ''::text, l.oid::text, x.privilege_type::text, x.is_grantable FROM pg_largeobject_metadata l CROSS JOIN LATERAL aclexplode(COALESCE(l.lomacl, acldefault('L', l.lomowner))) x WHERE x.grantee = (SELECT oid FROM wanted) UNION ALL SELECT 'foreign-data-wrapper', ''::text, f.fdwname::text, x.privilege_type::text, x.is_grantable FROM pg_foreign_data_wrapper f CROSS JOIN LATERAL aclexplode(COALESCE(f.fdwacl, acldefault('F', f.fdwowner))) x WHERE x.grantee = (SELECT oid FROM wanted) UNION ALL SELECT 'foreign-server', ''::text, s.srvname::text, x.privilege_type::text, x.is_grantable FROM pg_foreign_server s CROSS JOIN LATERAL aclexplode(COALESCE(s.srvacl, acldefault('S', s.srvowner))) x WHERE x.grantee = (SELECT oid FROM wanted) UNION ALL SELECT 'tablespace', ''::text, t.spcname::text, x.privilege_type::text, x.is_grantable FROM pg_tablespace t CROSS JOIN LATERAL aclexplode(COALESCE(t.spcacl, acldefault('t', t.spcowner))) x WHERE x.grantee = (SELECT oid FROM wanted) UNION ALL SELECT 'parameter', ''::text, p.parname::text, x.privilege_type::text, x.is_grantable FROM pg_parameter_acl p CROSS JOIN LATERAL aclexplode(p.paracl) x WHERE x.grantee = (SELECT oid FROM wanted) UNION ALL SELECT 'default-acl', COALESCE(n.nspname::text, ''), d.defaclobjtype::text, x.privilege_type::text, x.is_grantable FROM pg_default_acl d LEFT JOIN pg_namespace n ON n.oid = d.defaclnamespace CROSS JOIN LATERAL aclexplode(d.defaclacl) x WHERE x.grantee = (SELECT oid FROM wanted)) SELECT object_kind, schema_name, object_name, privilege_type, is_grantable FROM acl ORDER BY object_kind, schema_name, object_name, privilege_type